3	export function generatePageHTML(page: ParsedPage): string {
4	  const { frontmatter, html, slug } = page;
5	  const date = frontmatter.date ? new Date(frontmatter.date).toLocaleDateString() : '';
6	  const tagsList = Array.isArray(frontmatter.tags) ? frontmatter.tags.join(', ') : '';
7	
8	  return `<!DOCTYPE html>
9	<html lang="en">
10	<head>
11	  <meta charset="UTF-8">
12	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
13	  <title>${escapeHtml(frontmatter.title)}</title>
14	  <style>
15	    body {
