38	    <div class="meta">
39	      ${date ? `<div>Published: ${date}</div>` : ''}
40	      ${tagsList ? `<div class="tags">${frontmatter.tags!.map((tag: string) => `<span class="tag">${escapeHtml(tag)}</span>`).join('')}</div>` : ''}
