50	export function generateIndexHTML(pages: ParsedPage[]): string {
51	  const sortedPages = pages.sort((a, b) => {
52	    const dateA = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
53	    const dateB = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
54	    return dateB - dateA;
55	  });
56	
57	  const pageList = sortedPages
58	    .map(page => {
59	      const date = page.frontmatter.date ? new Date(page.frontmatter.date).toLocaleDateString() : 'No date';
60	      return `<li>
61	  <a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.frontmatter.title)}</a>
62	  <span class="date">${date}</span>
63	</li>`;
64	    })
65	    .join('\n');
66	
67	  return `<!DOCTYPE html>
68	<html lang="en">
69	<head>
70	  <meta charset="UTF-8">
71	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
72	  <title>Site Index</title>
73	  <style>
74	    body {
75	      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
76	      line-height: 1.6;
77	      max-width: 800px;
78	      margin: 0 auto;
79	      padding: 2rem;
80	      color: #333;
81	    }
82	    h1 { font-size: 2.5rem; margin-bottom: 2rem; }
83	    ul { list-style: none; padding: 0; }
84	    li {
85	      padding: 1rem 0;
86	      border-bottom: 1px solid #e0e0e0;
87	      display: flex;
88	      justify-content: space-between;
89	      align-items: center;
90	    }
91	    a { color: #0066cc; text-decoration: none; }
92	    a:hover { text-decoration: underline; }
93	    .date { color: #999; font-size: 0.9rem; }
94	  </style>
95	</head>
96	<body>
97	  <h1>Site Index</h1>
98	  <p>${pages.length} page${pages.length !== 1 ? 's' : ''} found</p>
99	  <ul>
100	${pageList}
101	  </ul>
102	</body>
103	</html>`;
104	}
