106	function escapeHtml(text: string): string {
107	  const map: { [key: string]: string } = {
108	    '&': '&amp;',
109	    '<': '&lt;',
110	    '>': '&gt;',
111	    '"': '&quot;',
112	    "'": '&#039;',
113	  };
114	  return text.replace(/[&<>"']/g, char => map[char]);
115	}
