1	import matter from 'gray-matter';
2	import { marked } from 'marked';
3	
4	export interface PageFrontmatter {
5	  title: string;
6	  date?: string;
7	  tags?: string[];
8	  [key: string]: any;
9	}
10	
11	export interface ParsedPage {
12	  frontmatter: PageFrontmatter;
13	  html: string;
14	  slug: string;
15	}
16	
17	export async function parseMarkdown(content: string, slug: string): Promise<ParsedPage> {
18	  const { data, content: markdown } = matter(content);
19	
20	  const frontmatter: PageFrontmatter = {
21	    title: data.title || 'Untitled',
22	    date: data.date,
23	    tags: data.tags || [],
24	    ...data,
25	  };
26	
27	  const html = await marked(markdown);
28	
29	  return {
30	    frontmatter,
31	    html,
32	    slug,
33	  };
34	}
