3	import fs from 'fs';
4	import path from 'path';
5	import { parseMarkdown } from './parser';
6	import { generatePageHTML, generateIndexHTML } from './generator';
7	
8	interface CliOptions {
9	  content: string;
10	  output: string;
11	}
12	
13	function parseArgs(): CliOptions {
14	  const args = process.argv.slice(2);
15	  const options: CliOptions = {
16	    content: './content',
17	    output: './dist',
18	  };
19	
20	  for (let i = 0; i < args.length; i++) {
21	    if (args[i] === '--content' && args[i + 1]) {
22	      options.content = args[i + 1];
23	      i++;
24	    } else if (args[i] === '--output' && args[i + 1]) {
25	      options.output = args[i + 1];
26	      i++;
27	    }
28	  }
29	
30	  return options;
31	}
32	
33	async function build(options: CliOptions): Promise<void> {
34	  const { content: contentDir, output: outputDir } = options;
35	
36	  if (!fs.existsSync(contentDir)) {
37	    console.error(`Error: Content directory "${contentDir}" does not exist`);
38	    process.exit(1);
39	  }
40	
41	  if (!fs.existsSync(outputDir)) {
42	    fs.mkdirSync(outputDir, { recursive: true });
43	  }
44	
45	  const files = fs.readdirSync(contentDir).filter(file => file.endsWith('.md'));
46	
47	  if (files.length === 0) {
48	    console.warn(`Warning: No markdown files found in "${contentDir}"`);
49	  }
50	
51	  const pages = [];
52	
53	  for (const file of files) {
54	    const filePath = path.join(contentDir, file);
55	    const content = fs.readFileSync(filePath, 'utf-8');
56	    const slug = path.parse(file).name;
57	
58	    try {
59	      const page = await parseMarkdown(content, slug);
60	      pages.push(page);
61	
62	      const outputFile = path.join(outputDir, `${slug}.html`);
63	      const html = generatePageHTML(page);
64	      fs.writeFileSync(outputFile, html, 'utf-8');
65	      console.log(`✓ Generated ${outputFile}`);
66	    } catch (error) {
67	      console.error(`Error processing ${file}:`, error);
68	      process.exit(1);
69	    }
70	  }
71	
72	  const indexFile = path.join(outputDir, 'index.html');
73	  const indexHtml = generateIndexHTML(pages);
74	  fs.writeFileSync(indexFile, indexHtml, 'utf-8');
75	  console.log(`✓ Generated ${indexFile}`);
76	
77	  console.log(`\nBuild complete: ${pages.length} page${pages.length !== 1 ? 's' : ''} generated`);
78	}
79	
80	const command = process.argv[2];
81	
82	if (command === 'build' || !command) {
83	  const options = parseArgs();
84	  build(options).catch(error => {
85	    console.error('Build failed:', error);
86	    process.exit(1);
87	  });
88	} else {
89	  console.error(`Unknown command: ${command}`);
90	  console.error('Usage: ssg build [--content <dir>] [--output <dir>]');
91	  process.exit(1);
92	}
