20	class TemplateEngine {
21	  private templateDir: string;
22	  private layoutsDir: string;
23	  private partialsDir: string;
24	  private compiledTemplates: Map<string, HandlebarsTemplateDelegate> = new Map();
25	  private compiledLayouts: Map<string, HandlebarsTemplateDelegate> = new Map();
26	
27	  constructor(options: TemplateEngineOptions) {
28	    this.templateDir = options.templateDir;
29	    this.layoutsDir = path.join(this.templateDir, 'layouts');
30	    this.partialsDir = path.join(this.templateDir, 'partials');
31	    this.registerPartials();
32	  }
33	
34	  private registerPartials(): void {
35	    if (!fs.existsSync(this.partialsDir)) {
36	      return;
37	    }
38	
39	    const partialFiles = fs.readdirSync(this.partialsDir).filter(file => file.endsWith('.hbs'));
40	
41	    for (const file of partialFiles) {
42	      const partialName = path.parse(file).name;
43	      const partialPath = path.join(this.partialsDir, file);
44	      const partialContent = fs.readFileSync(partialPath, 'utf-8');
45	      Handlebars.registerPartial(partialName, partialContent);
46	    }
47	  }
48	
49	  private getLayoutPath(layoutName: string): string {
50	    return path.join(this.layoutsDir, `${layoutName}.hbs`);
51	  }
52	
53	  private getTemplatePath(templateName: string): string {
54	    return path.join(this.templateDir, `${templateName}.hbs`);
55	  }
56	
57	  private loadTemplate(templatePath: string): string {
58	    if (!fs.existsSync(templatePath)) {
59	      throw new Error(`Template not found: ${templatePath}`);
60	    }
61	    return fs.readFileSync(templatePath, 'utf-8');
62	  }
63	
64	  private compileTemplate(templateContent: string): HandlebarsTemplateDelegate {
65	    return Handlebars.compile(templateContent);
66	  }
67	
68	  private renderLayout(layoutName: string, content: string, data: TemplateData): string {
69	    const layoutPath = this.getLayoutPath(layoutName);
70	
71	    if (!this.compiledLayouts.has(layoutName)) {
72	      const layoutContent = this.loadTemplate(layoutPath);
73	      this.compiledLayouts.set(layoutName, this.compileTemplate(layoutContent));
74	    }
75	
76	    const layoutTemplate = this.compiledLayouts.get(layoutName)!;
77	    return layoutTemplate({ ...data, body: content });
78	  }
79	
80	  private renderTemplate(templateName: string, data: TemplateData): string {
81	    const templatePath = this.getTemplatePath(templateName);
82	
83	    if (!this.compiledTemplates.has(templateName)) {
84	      const templateContent = this.loadTemplate(templatePath);
85	      this.compiledTemplates.set(templateName, this.compileTemplate(templateContent));
86	    }
87	
88	    const template = this.compiledTemplates.get(templateName)!;
89	    return template(data);
90	  }
91	
92	  renderPage(page: ParsedPage, templateName?: string, layoutName?: string): string {
93	    const data: TemplateData = {
94	      title: page.frontmatter.title,
95	      date: page.frontmatter.date,
96	      tags: page.frontmatter.tags,
97	      slug: page.slug,
98	      html: page.html,
99	      body: page.html,
100	      ...page.frontmatter,
101	    };
102	
103	    let renderedContent: string;
104	
105	    if (templateName) {
106	      renderedContent = this.renderTemplate(templateName, data);
107	    } else {
108	      renderedContent = page.html;
109	    }
110	
111	    if (layoutName) {
112	      data.body = renderedContent;
113	      renderedContent = this.renderLayout(layoutName, renderedContent, data);
114	    }
115	
116	    return renderedContent;
117	  }
118	
119	  hasTemplate(templateName: string): boolean {
120	    const templatePath = this.getTemplatePath(templateName);
121	    return fs.existsSync(templatePath);
122	  }
123	
124	  hasLayout(layoutName: string): boolean {
125	    const layoutPath = this.getLayoutPath(layoutName);
126	    return fs.existsSync(layoutPath);
127	  }
128	}
129	
130	export { TemplateEngine, TemplateEngineOptions, TemplateData };
