15	function parseArgs(): CliOptions {
16	  const args = process.argv.slice(2);
17	  const options: CliOptions = {
18	    content: './content',
19	    output: './dist',
20	  };
21	
22	  for (let i = 0; i < args.length; i++) {
23	    if (args[i] === '--content' && args[i + 1]) {
24	      options.content = args[i + 1];
25	      i++;
26	    } else if (args[i] === '--output' && args[i + 1]) {
27	      options.output = args[i + 1];
28	      i++;
29	    } else if (args[i] === '--templates' && args[i + 1]) {
30	      options.templates = args[i + 1];
31	      i++;
32	    }
33	  }
34	
35	  return options;
