38	async function build(options: CliOptions): Promise<void> {
39	  const { content: contentDir, output: outputDir, templates: templatesDir } = options;
40	
41	  if (!fs.existsSync(contentDir)) {
42	    console.error(`Error: Content directory "${contentDir}" does not exist`);
43	    process.exit(1);
44	  }
45	
46	  if (!fs.existsSync(outputDir)) {
47	    fs.mkdirSync(outputDir, { recursive: true });
48	  }
49	
50	  let templateEngine: TemplateEngine | undefined;
51	  if (templatesDir && fs.existsSync(templatesDir)) {
52	    templateEngine = new TemplateEngine({ templateDir: templatesDir });
53	  }
54	
55	  const files = fs.readdirSync(contentDir).filter(file => file.endsWith('.md'));
56	
57	  if (files.length === 0) {
58	    console.warn(`Warning: No markdown files found in "${contentDir}"`);
59	  }
60	
61	  const pages = [];
62	
63	  for (const file of files) {
64	    const filePath = path.join(contentDir, file);
65	    const content = fs.readFileSync(filePath, 'utf-8');
66	    const slug = path.parse(file).name;
67	
68	    try {
69	      const page = await parseMarkdown(content, slug);
70	      pages.push(page);
71	
72	      const outputFile = path.join(outputDir, `${slug}.html`);
73	      const html = generatePageHTML(page, templateEngine);
74	      fs.writeFileSync(outputFile, html, 'utf-8');
75	      console.log(`✓ Generated ${outputFile}`);
76	    } catch (error) {
77	      console.error(`Error processing ${file}:`, error);
78	      process.exit(1);
79	    }
80	  }
81	
82	  const indexFile = path.join(outputDir, 'index.html');
