85	  console.log(`✓ Generated ${indexFile}`);
86	
87	  console.log(`\nBuild complete: ${pages.length} page${pages.length !== 1 ? 's' : ''} generated`);
88	}
89	
90	const command = process.argv[2];
91	
92	if (command === 'build' || !command) {
93	  const options = parseArgs();
94	  build(options).catch(error => {
95	    console.error('Build failed:', error);
96	    process.exit(1);
97	  });
98	} else {
99	  console.error(`Unknown command: ${command}`);
100	  console.error('Usage: ssg build [--content <dir>] [--output <dir>]');
101	  process.exit(1);
102	}
